TLM.f("Commune/Coronatio",{"officium":"Missa Votiva in Creatione et Coronatione Papae et in die anniversarii","rule":["Gloria","Credo"],"sections":{"Introitus":[{"k":"ref","la":"Eccli 45:30"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Alleluia, alleluia.)"},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David: et omnis mansuetúdinis ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Státuit ei Dóminus testaméntum pacis, et príncipem fecit eum: ut sit illi sacerdótii dígnitas in ætérnum. (Alleluia, alleluia.)"}],"Oratio":[{"k":"text","la":"Deus, ómnium fidélium pastor et rector, fámulum tuum N.p, quem pastórem Ecclésiæ tuæ præésse voluísti, propítius réspice: da ei, quǽsumus, verbo et exémplo, quibus præest, profícere; ut ad vitam, una cum grege sibi crédito, pervéniat sempitérnam."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 1:1-7"},{"k":"text","la":"Petrus, Apóstolus Jesu Christi, eléctis ádvenis dispersiónis Ponti, Galátiæ, Cappadóciæ, Asiæ et Bithýniæ secúndum præsciéntiam Dei Patris, in sanctificatiónem Spíritus, in obœdiéntiam, et aspersiónem sánguinis Jesu Christi: grátia vobis et pax multiplicétur. Benedíctus Deus et Pater Dómini nostri Jesu Christi, qui secúndum misericórdiam suam magnam regenerávit nos in spem vivam, per resurrectiónem Jesu Christi ex mórtuis, in hereditátem incorruptíbilem et incontaminátam et immarcescíbilem, conservátam in cœlis in vobis, qui in virtúte Dei custodímini per fidem in salútem, parátam revelári in témpore novíssimo. In quo exsultábitis, módicum nunc si opórtet contristári in váriis tentatiónibus: ut probátio vestræ fídei multo pretiósior auro [quod per ignem probatur] inveniátur in laudem et glóriam et honórem, in revelatióne Jesu Christi, Dómini nostri."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 106:8"},{"k":"text","la":"Confitéantur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum"},{"k":"ref","la":"Matt 6:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"Tractus":[{"k":"ref","la":"Matt 16:18-19"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam."},{"k":"text","la":"Et portæ ínferi non prævalébunt advérsus eam: et tibi dabo claves regni cœlórum.","mark":"V"},{"k":"text","la":"Quodcúmque ligáveris super terram, erit ligátum et in cœlis.","mark":"V"},{"k":"text","la":"Et quodcúmque sólveris super terram, erit solútum et in cœlis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Matt 16:18-19"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam: et portæ ínferi non prævalébunt advérsus eam: et tibi dabo claves regni cœlórum. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Oblátis, quǽsumus, Dómine, placáre munéribus: et fámulum tuum N.p, quem pastórem Ecclésiæ tuæ præésse voluísti, assídua protectióne gubérna."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Hæc nos, quǽsumus, Dómine, divíni sacraménti percéptio prótegat: et fámulum tuum N.p, quem pastórem Ecclésiæ tuæ præésse voluísti; una cum commísso sibi grege, salvet semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Secreta1":[{"k":"text","la":"Múnera, quæ tibi, Dómine, lætántes offérimus, súscipe benígnus, et præsta: ut, intercedénte beáto N., Ecclésia tua et fídei integritáte lætétur, et témporum tranquillitáte semper exúltet."},{"k":"macro","name":"Per Dominum"}],"Postcommunio1":[{"k":"text","la":"Multíplica, quǽsumus, Dómine, in Ecclésia tua spíritum grátiæ, quem dedísti: ut beáti N. (Mártyris tui atque) Summi Pontíficis deprecatióne nec pastóri obœdiéntia gregis nec gregi desit cura pastóris."},{"k":"macro","name":"Per Dominum"}]},"hr":{"023f6697e17ef599":{"t":"Bože, pastiru i vladaru svih vjernika, pogledaj milostivo na slugu svoga I. [Benedikta], koga si htio postaviti kao pastira na čelo Crkve svoje, i podaj mu, molimo, da riječju i primjerom prednjači onima kojima je pretpostavljen, te zajedno sa stadom sebi povjerenim dođe u život vječni.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → p","kn":"(Ili za Papu). Bože, pastiru i vladaru svih vjernika, pogledaj milostivo na slugu svoga I., koga si htio postaviti pastirom na čelo Tvoje Crkve i podaj mu, molimo, da riječju i primjerom prednjači onima, kojima je predpostavljen, te zajedno Sa sebi povjerenim ,s;tadom uđe u život vječni po G. n.","knRef":"Kniewald 1942, str. 850–851 (snimka 426) (OCR)"},"2060790f921b3d51":{"t":"Dobrostivo primi, molimo, Gospodine, prikazane darove i neprestanom zaštitom vodi slugu svoga I. [Benedikta] koga si postavio da bude pastir Crkve tvoje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → p","kn":".Ili za Papu). Molimo. Gospodine, dostoj nam se oprostiti po prikazanim darovima i neprestanom zaštitom upravlja,! slugu svoga I., koga si htio postaviti pastirom Crkvi svojoj, po G. n.","knRef":"Kniewald 1942, str. 852–853 (snimka 427) (OCR)"},"a452e67b263a74f0":{"t":"Ovo primanje božanskog otajstva neka nas. molimo, Gospodine, čuva, a slugu tvoga I. [Benedikta], koga si postavio pastirom svoje Crkve, neka uvijek spašava i brani zajedrio s povjerenim mu stadom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"∅ → p","kn":"(IH za Papu). Molimo. Gospodine, da nas ovaj primitak božanske taj.ne čuva i da slugu Tvoga I., koga si htio postaviti pastirom nad Crkvom svojom, zajedno s povjerenim mu stadom, uvijek štiti i spasava, po G. n.","knRef":"Kniewald 1942, str. 852–853 (snimka 427) (OCR)"}}});
